ALTER TABLE users ADD COLUMN mc_uuid TEXT;
ALTER TABLE users ADD COLUMN mc_name TEXT;
ALTER TABLE users ADD COLUMN xp INTEGER NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN play_minutes INTEGER NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_mc_uuid ON users(mc_uuid);
CREATE TABLE IF NOT EXISTS mc_players ( uuid TEXT PRIMARY KEY, name TEXT NOT NULL, updated_at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS idx_mc_players_name ON mc_players(name COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS mc_stats ( uuid TEXT NOT NULL, ptero_uuid TEXT NOT NULL, play_minutes INTEGER NOT NULL DEFAULT 0, stats TEXT, advancements TEXT, updated_at INTEGER NOT NULL, PRIMARY KEY (uuid, ptero_uuid) );
CREATE TABLE IF NOT EXISTS mc_links ( user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, mc_uuid TEXT NOT NULL, mc_name TEXT NOT NULL, code TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS quests ( id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, title_es TEXT, description TEXT, description_es TEXT, xp INTEGER NOT NULL, kind TEXT NOT NULL DEFAULT 'manual', criteria_type TEXT, criteria_key TEXT, criteria_target INTEGER, server_id TEXT REFERENCES servers(id) ON DELETE SET NULL, active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS quest_completions ( id INTEGER PRIMARY KEY AUTOINCREMENT, quest_id INTEGER NOT NULL REFERENCES quests(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'pending', proof TEXT, review_note TEXT, reviewed_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, reviewed_at INTEGER, UNIQUE (quest_id, user_id) );
CREATE INDEX IF NOT EXISTS idx_completions_status ON quest_completions(status, created_at);
INSERT INTO quests (title, title_es, description, description_es, xp, kind, criteria_type, criteria_key, criteria_target, sort_order, created_at, updated_at) SELECT 'Stone Age', 'Edad de piedra', 'Mine your first stone.', 'Mina tu primera piedra.', 50, 'auto', 'advancement', 'minecraft:story/mine_stone', NULL, 1, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE NOT EXISTS (SELECT 1 FROM quests);
INSERT INTO quests (title, title_es, description, description_es, xp, kind, criteria_type, criteria_key, criteria_target, sort_order, created_at, updated_at) SELECT 'Diamonds!', '¡Diamantes!', 'Get the Diamonds! advancement.', 'Consigue el logro ¡Diamantes!.', 250, 'auto', 'advancement', 'minecraft:story/mine_diamond', NULL, 2, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE (SELECT COUNT(*) FROM quests) = 1;
INSERT INTO quests (title, title_es, description, description_es, xp, kind, criteria_type, criteria_key, criteria_target, sort_order, created_at, updated_at) SELECT 'Miner', 'Minero', 'Mine 1,000 stone.', 'Mina 1,000 bloques de piedra.', 200, 'auto', 'stat', 'minecraft:mined/minecraft:stone', 1000, 3, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE (SELECT COUNT(*) FROM quests) = 2;
INSERT INTO quests (title, title_es, description, description_es, xp, kind, criteria_type, criteria_key, criteria_target, sort_order, created_at, updated_at) SELECT 'Free the End', 'Libera el End', 'Defeat the Ender Dragon.', 'Derrota al Ender Dragon.', 1000, 'auto', 'advancement', 'minecraft:end/kill_dragon', NULL, 4, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE (SELECT COUNT(*) FROM quests) = 3;
INSERT INTO quests (title, title_es, description, description_es, xp, kind, sort_order, created_at, updated_at) SELECT 'Show off your base', 'Presume tu base', 'Build a base and submit a screenshot link (Discord, Imgur…).', 'Construye una base y envía el enlace a una captura (Discord, Imgur…).', 150, 'manual', 5, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE (SELECT COUNT(*) FROM quests) = 4;
